'use strict';
const test=require('node:test'),assert=require('node:assert/strict');
const {buildSnapshot,querySnapshot,createSnapshotStore,haversineKm,coord}=require('./snapshot-france');
const row=(id,lat=43.3,lon=5.4,price=1.7)=>({id,geom:{lat,lon},gazole_prix:price,e10_prix:1.8});
const snapshot=()=>buildSnapshot([row('b'),row('a'),row('c',45,5)],{version:'v1',createdAt:'2026-11-12T10:00:00Z'});
const q={lat:43.3,lon:5.4,radiusKm:5,fuel:'Gazole'};
test('build stable sorted',()=>assert.deepEqual(snapshot().stations.map(x=>x.id),['a','b','c']));
test('count',()=>assert.equal(snapshot().count,3));
test('checksum deterministic',()=>assert.equal(snapshot().checksum,snapshot().checksum));
test('checksum changes with price',()=>assert.notEqual(snapshot().checksum,buildSnapshot([row('b',43.3,5.4,2),row('a'),row('c',45,5)],{version:'v2'}).checksum));
test('invalid version',()=>assert.throws(()=>buildSnapshot([],{version:'../bad'})));
test('invalid timestamp',()=>assert.throws(()=>buildSnapshot([],{version:'v',createdAt:'abc'})));
test('duplicate ids',()=>assert.throws(()=>buildSnapshot([row('a'),row('a')],{version:'v'})));
test('invalid coords',()=>assert.throws(()=>buildSnapshot([row('a',99,5)],{version:'v'})));
test('invalid price',()=>assert.throws(()=>buildSnapshot([row('a',43,5,-1)],{version:'v'})));
test('missing price retained',()=>assert.equal(buildSnapshot([{id:'a',geom:{lat:43,lon:5}}],{version:'v'}).stations[0].prices.Gazole,null));
test('coords legacy',()=>assert.deepEqual(coord({latitude:4330000,longitude:540000}),{lat:43.3,lon:5.4}));
test('haversine zero',()=>assert.equal(haversineKm({lat:1,lon:1},{lat:1,lon:1}),0));
test('radius filter',()=>assert.equal(querySnapshot(snapshot(),q).total,2));
test('fuel filter',()=>assert.equal(querySnapshot(snapshot(),{...q,fuel:'SP95'}).total,0));
test('pagination first',()=>assert.equal(querySnapshot(snapshot(),{...q,limit:1}).nextCursor,1));
test('pagination last',()=>assert.equal(querySnapshot(snapshot(),{...q,limit:1,offset:1}).nextCursor,null));
test('pagination out of bounds',()=>assert.equal(querySnapshot(snapshot(),{...q,offset:50}).results.length,0));
test('version in response',()=>assert.equal(querySnapshot(snapshot(),q).snapshot,'v1'));
test('invalid query',()=>assert.throws(()=>querySnapshot(snapshot(),{...q,lat:100})));
test('invalid fuel',()=>assert.throws(()=>querySnapshot(snapshot(),{...q,fuel:'none'})));
test('limit cap',()=>assert.throws(()=>querySnapshot(snapshot(),{...q,limit:101})));
test('stage without publish invisible',()=>{const store=createSnapshotStore();store.stage(snapshot());assert.equal(store.getActive(),null)});
test('atomic pointer change',()=>{const store=createSnapshotStore(),s1=snapshot(),s2=buildSnapshot([row('z')],{version:'v2'});store.stage(s1);store.publish('v1');const before=store.query(q);store.stage(s2);assert.equal(store.query(q).snapshot,'v1');store.publish('v2');assert.equal(store.query(q).snapshot,'v2');assert.equal(before.total,2)});
test('unknown version',()=>assert.throws(()=>createSnapshotStore().publish('missing')));
test('duplicate version rejected',()=>{const store=createSnapshotStore();store.stage(snapshot());assert.throws(()=>store.stage(snapshot()))});
test('not ready',()=>assert.throws(()=>createSnapshotStore().query(q)));
test('immutable stations',()=>assert.ok(Object.isFrozen(snapshot().stations)));
test('missing snapshot',()=>assert.throws(()=>querySnapshot(null,q)));
